static bool sample_once(calibrate_app* me)
{
    analog_input_t* input;
    int32_t code;

    input = board_input(me);
    if ( input == NULL || analog_input_read_sample(input, &code) != ANALOG_INPUT_OK ) {
        return false;
    }

    ++me->sampleCount;
    if ( me->sampleCount > CAL_SAMPLE_DISCARD ) {
        me->sampleSum += code;
    }
    return true;
}

static bool reference_codes(uint8_t type, int32_t* ideal_low, int32_t* ideal_high)
{
    analog_input_type_t input_type;
    float physical_low;
    float physical_high;

    switch ( type ) {
        case CAL_DATA_TYPE_THERMOCOUPLE:
            input_type    = ANALOG_INPUT_TYPE_THERMOCOUPLE;
            physical_low  = CAL_REFERENCE_TC_LOW_MV;
            physical_high = CAL_REFERENCE_TC_HIGH_MV;
            break;
        case CAL_DATA_TYPE_PT100:
            input_type    = ANALOG_INPUT_TYPE_PT100;
            physical_low  = CAL_REFERENCE_PT100_LOW_OHM;
            physical_high = CAL_REFERENCE_PT100_HIGH_OHM;
            break;
        case CAL_DATA_TYPE_4_20MA:
            input_type    = ANALOG_INPUT_TYPE_4_20MA;
            physical_low  = CAL_REFERENCE_4_20MA_LOW_MA;
            physical_high = CAL_REFERENCE_4_20MA_HIGH_MA;
            break;
        case CAL_DATA_TYPE_0_10V:
            input_type    = ANALOG_INPUT_TYPE_0_10V;
            physical_low  = CAL_REFERENCE_0_10V_LOW_V;
            physical_high = CAL_REFERENCE_0_10V_HIGH_V;
            break;
        default:
            return false;
    }

    if ( analog_input_board_code_from_physical(input_type, physical_low, ideal_low)
             != ANALOG_INPUT_OK
         || analog_input_board_code_from_physical(input_type, physical_high, ideal_high)
                != ANALOG_INPUT_OK ) {
        return false;
    }
    return true;
}

