static cal_error_t commit(calibrate_app* me)
{
    cal_save_evt_t* save_evt;
    QActive* storage;
    int32_t ideal_low;
    int32_t ideal_high;
    int64_t ideal_span;
    int64_t raw_span;
    int64_t gain_micro;
    int64_t offset_code;

    if ( me->rawLow >= CAL_RAW_CODE_LIMIT || me->rawLow <= -CAL_RAW_CODE_LIMIT
         || me->rawHigh >= CAL_RAW_CODE_LIMIT
         || me->rawHigh <= -CAL_RAW_CODE_LIMIT ) {
        return CAL_ERROR_CAPTURE_FAILED;
    }
    if ( reference_codes(me->type, &ideal_low, &ideal_high) == false ) {
        return CAL_ERROR_REFERENCE_FAILED;
    }

    ideal_span = (int64_t)ideal_high - (int64_t)ideal_low;
    raw_span   = (int64_t)me->rawHigh - (int64_t)me->rawLow;
    if ( raw_span == 0
         || magnitude(raw_span) * 10U < magnitude(ideal_span) ) {
        return CAL_ERROR_SPAN_TOO_SMALL;
    }

    gain_micro = (ideal_span * 1000000LL) / raw_span;
    if ( gain_micro < CAL_GAIN_MICRO_MIN || gain_micro > CAL_GAIN_MICRO_MAX ) {
        return CAL_ERROR_GAIN_OUT_OF_RANGE;
    }

    offset_code = (int64_t)ideal_low
                  - (gain_micro * (int64_t)me->rawLow) / 1000000LL;
    if ( offset_code > CAL_OFFSET_CODE_LIMIT
         || offset_code < -CAL_OFFSET_CODE_LIMIT ) {
        return CAL_ERROR_OFFSET_OUT_OF_RANGE;
    }

    storage = me->storage;
    if ( storage == NULL ) {
        return CAL_ERROR_SAVE_FAILED;
    }
    save_evt = Q_NEW(cal_save_evt_t, CAL_SAVE_SIG);
    if ( save_evt == NULL ) {
        return CAL_ERROR_SAVE_FAILED;
    }

    me->gain   = (int32_t)gain_micro;
    me->offset = (int32_t)offset_code;
    me->pending.entry[me->type].gain_micro  = me->gain;
    me->pending.entry[me->type].offset_code = me->offset;
    me->pending.valid_mask |= (uint8_t)(1U << me->type);
    me->pending.version = CAL_DATA_VERSION;
    me->pending.size    = (uint16_t)sizeof(me->pending);

    save_evt->channel = me->channel;
    save_evt->record  = &me->pending;
    QACTIVE_POST(storage, &save_evt->super, me->container);
    return CAL_ERROR_NONE;
}

