//${App::calibrate_app::SM::idle} ............................................
QState calibrate_app_idle(calibrate_app * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${App::calibrate_app::SM::idle}
        case Q_ENTRY_SIG: {
            me->status = CAL_STATUS_IDLE;
            me->error  = CAL_ERROR_NONE;
            status_ = Q_HANDLED();
            break;
        }
        //${App::calibrate_app::SM::idle::CAL_ENTER}
        case CAL_ENTER_SIG: {
            me->status = CAL_STATUS_IDLE;
            me->error  = CAL_ERROR_NONE;
            memset(&me->pending, 0, sizeof(me->pending));
            me->rawLow  = 0L;
            me->rawHigh = 0L;
            me->gain    = 0L;
            me->offset  = 0L;
            status_ = Q_HANDLED();
            break;
        }
        //${App::calibrate_app::SM::idle::CAL_SELECT}
        case CAL_SELECT_SIG: {
            //${App::calibrate_app::SM::idle::CAL_SELECT::[select_valid(e)]}
            if (select_valid(e)) {
                start_select(me, e);
                status_ = Q_TRAN(&calibrate_app_active);
            }
            //${App::calibrate_app::SM::idle::CAL_SELECT::[else]}
            else {
                me->error = CAL_ERROR_INVALID_CHANNEL_TYPE;
                status_ = Q_TRAN(&calibrate_app_error);
            }
            break;
        }
        //${App::calibrate_app::SM::idle::CAL_LOW, CAL_HIGH, CAL_COMMIT}
        case CAL_LOW_SIG: // intentionally fall through
        case CAL_HIGH_SIG: // intentionally fall through
        case CAL_COMMIT_SIG: {
            me->error = CAL_ERROR_NOT_SELECTED;
            status_ = Q_TRAN(&calibrate_app_error);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${App::calibrate_app::SM::active} ..........................................
QState calibrate_app_active(calibrate_app * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${App::calibrate_app::SM::active}
        case Q_EXIT_SIG: {
            QActive* channel;

            stop_component_timers(me);
            channel = channel_app_get(me->channel);
            if ( channel != NULL ) {
                QACTIVE_POST(channel, &cal_exit_evt, me->container);
            } else {
                elog_warn("calibrate", "channel %u has no AO to resume",
                          (unsigned)me->channel);
            }
            status_ = Q_HANDLED();
            break;
        }
        //${App::calibrate_app::SM::active::initial}
        case Q_INIT_SIG: {
            status_ = Q_TRAN(&calibrate_app_waiting_channel);
            break;
        }
        //${App::calibrate_app::SM::active::CAL_EXIT, CAL_ABORT}
        case CAL_EXIT_SIG: // intentionally fall through
        case CAL_ABORT_SIG: {
            status_ = Q_TRAN(&calibrate_app_idle);
            break;
        }
        //${App::calibrate_app::SM::active::CAL_SELECT, CAL_LOW, CAL_HIGH, C~}
        case CAL_SELECT_SIG: // intentionally fall through
        case CAL_LOW_SIG: // intentionally fall through
        case CAL_HIGH_SIG: // intentionally fall through
        case CAL_COMMIT_SIG: {
            me->error = CAL_ERROR_BUSY;
            status_ = Q_HANDLED();
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

